const TARGET_GROUPS = {
  '919493561700-1545803250@g.us': 'MSK',
  '919930599976-1613022548@g.us': 'IPV',
  '120363427391049099@g.us':      'MoneyMavericks'
};

const body = $input.first().json.body || $input.first().json;
const data = body.data || {};
const key  = data.key || {};
const msg  = data.message || {};

const groupJid  = key.remoteJid || '';
const isGroup   = groupJid.endsWith('@g.us');
const fromMe    = key.fromMe === true;
const msgId     = key.id || '';
const senderJid = data.participant || key.participant || '';
const pushName  = data.pushName || '';
const tsUnix    = data.messageTimestamp || Math.floor(Date.now()/1000);

// Extract text body from any of the variants
const text = (
  msg.conversation ||
  (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
  (msg.imageMessage && msg.imageMessage.caption) ||
  (msg.videoMessage && msg.videoMessage.caption) ||
  ''
).toString();

if (!isGroup || fromMe || !text.trim()) {
  return [];
}

const sourceGroup = TARGET_GROUPS[groupJid];
if (!sourceGroup) return [];

return [{
  json: {
    message_id: msgId,
    group_jid: groupJid,
    source_group: sourceGroup,
    sender_jid: senderJid,
    push_name: pushName,
    body: text,
    posted_at: new Date(tsUnix * 1000).toISOString()
  }
}];

const SIGNAL_RE = /(?:(?<trade_type>POSITIONAL\s+TRADE|INTRADAY\s+TRADE|BTST\s+TRADE)\s*[\r\n]+)?\s*(?<stock>[A-Z][A-Z0-9&.\- ]{1,40}?)\s*[\r\n]+\s*Looks\s+Good\s+ABOVE\s+(?<entry>\d+(?:\.\d+)?)\s*[\r\n]+\s*SL\s+(?<sl>\d+(?:\.\d+)?)\s*[\r\n]+\s*Targets?\s+(?<targets>[\d.\-+\s]+?)(?<points>\s*points?\s+from\s+entry)?(?:\s*[\r\n]|$)/is;

const TARGET_HIT_RE = /🔥.*We shared the research/is;

const input = $input.first().json;
const body  = (input.body || '').toString();

if (TARGET_HIT_RE.test(body)) return [];

const m = body.match(SIGNAL_RE);
if (!m || !m.groups) return [];

const g = m.groups;
const entry = parseFloat(g.entry);
const sl    = parseFloat(g.sl);
const rawTargets = g.targets.replace(/[+\s]+/g, '-').replace(/-+/g,'-').replace(/^-|-$/g,'').split('-').filter(Boolean);
let targets = rawTargets.map(Number).filter(n => !isNaN(n));
const mode = g.points ? 'points_from_entry' : 'absolute';
if (mode === 'points_from_entry') targets = targets.map(t => Number((entry + t).toFixed(2)));

return [{
  json: {
    ...input,
    trade_type:      (g.trade_type || '').toUpperCase().trim() || null,
    stock_name_raw:  g.stock.replace(/\s+/g,' ').trim(),
    entry_price:     entry,
    stop_loss:       sl,
    targets,
    targets_mode:    mode,
    extractor:       'regex',
    confidence:      0.9
  }
}];

const prev = $('Regex extract signal').first().json;
const sym  = $input.first().json;
return [{ json: { ...prev, nse_symbol: sym.nse_symbol || null } }];
